package com.srenterprises.controller; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import com.srenterprises.service.*; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.security.crypto.password.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/users") @PreAuthorize("hasRole('SUPER_ADMIN')") public class AdminUserController { final UserRepository users; final PasswordEncoder passwords; final AuditService audit; AdminUserController(UserRepository u,PasswordEncoder p,AuditService a){users=u;passwords=p;audit=a;} record Create(@NotBlank String name,@Email String email,@Size(min=8) String password,@NotNull Role role){} record Update(Role role,Boolean active){} @GetMapping public Page<User> list(@RequestParam(defaultValue="0") int page){return users.findAll(PageRequest.of(page,25,Sort.by("createdAt").descending()));} @PostMapping public ResponseEntity<User> create(@RequestBody Create c){if(c.role()==Role.SUPER_ADMIN)throw new org.springframework.security.access.AccessDeniedException("SUPER_ADMIN creation is not permitted here");if(users.findByEmailIgnoreCase(c.email()).isPresent())return ResponseEntity.status(409).build();User u=new User();u.name=c.name();u.email=c.email().toLowerCase();u.passwordHash=passwords.encode(c.password());u.role=c.role();users.save(u);audit.record("ADMIN_CREATED","USER",u.id,"Created "+u.role+" user");return ResponseEntity.status(201).body(u);}@PutMapping("/{id}") public User update(@PathVariable UUID id,@RequestBody Update u){User target=users.findById(id).orElseThrow();if(u.role()!=null){if(u.role()==Role.SUPER_ADMIN)throw new org.springframework.security.access.AccessDeniedException("Cannot assign SUPER_ADMIN");target.role=u.role();}if(u.active()!=null)target.active=u.active();target.updatedAt=java.time.Instant.now();users.save(target);audit.record("USER_UPDATED","USER",id,"Updated privileged user");return target;} }
